import { useAnimationControls, useReducedMotion } from 'motion/react'
import { useCallback, useEffect, useImperativeHandle, useRef } from 'react'
import type { Ref } from 'react'

export type GestureTrigger = 'hover' | 'mount' | 'manual'

export interface GestureHandle {
  /** Play the gesture once. Resolves when it has finished and returned to rest. */
  play: () => Promise<void>
}

export interface UseGestureOptions {
  trigger?: GestureTrigger
  /**
   * Hover-intent dwell in ms. The gesture is not a hover state — it is a discrete
   * event, so it waits a breath before it plays, and once playing it is never
   * cancelled mid-flight. Intent guards the start, completion guards the end.
   */
  dwell?: number
  handleRef?: Ref<GestureHandle>
}

/**
 * The trigger discipline shared by every icon:
 *
 *  - hover: pointer enter starts a short dwell timer; leaving during the dwell
 *    cancels the *start*, never a running gesture. A gesture that has begun
 *    always finishes — every "animate" variant is authored to end exactly on
 *    the resting picture, so completion IS the reset.
 *  - mount: plays once when the component appears.
 *  - manual: only plays via the imperative handle.
 *
 * prefers-reduced-motion turns every play into a no-op; the icon stays a
 * perfectly good static icon.
 */
export function useGesture({ trigger = 'hover', dwell = 110, handleRef }: UseGestureOptions = {}) {
  const controls = useAnimationControls()
  const reduced = useReducedMotion()
  const playing = useRef(false)
  const dwellTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const play = useCallback(async () => {
    if (playing.current || reduced) return
    playing.current = true
    try {
      await controls.start('animate')
      // The last keyframe of every part is its rest value, so this set() is
      // invisible — it just detaches the finished animation.
      controls.set('normal')
    } finally {
      playing.current = false
    }
  }, [controls, reduced])

  useImperativeHandle(handleRef, () => ({ play }), [play])

  useEffect(() => {
    if (trigger === 'mount') {
      const t = setTimeout(play, 200)
      return () => clearTimeout(t)
    }
  }, [trigger, play])

  const onPointerEnter = useCallback(() => {
    if (trigger !== 'hover') return
    dwellTimer.current = setTimeout(play, dwell)
  }, [trigger, dwell, play])

  const onPointerLeave = useCallback(() => {
    if (dwellTimer.current) {
      clearTimeout(dwellTimer.current)
      dwellTimer.current = null
    }
    // Deliberately no cancel here: a started gesture runs to completion.
  }, [])

  return {
    controls,
    play,
    hoverProps: trigger === 'hover' ? { onPointerEnter, onPointerLeave } : {},
  }
}

/**
 * House easing vocabulary.
 *
 * The rules these encode:
 *  - Arriving is always an ease-out. Leaving the frame is the one place ease-in is right.
 *  - A shape morphing on screen is the textbook ease-in-out case.
 *  - A pen leaves fast and eases into its stop — that separates writing from a progress bar.
 *  - Nothing in flight is eased (a tossed key spins linearly; nothing torques it mid-air).
 *  - Anticipation/overshoot live in the curve, not in extra keyframes, when the motion
 *    is one continuous beat (負の y1 = 予備動作, y2 > 1 = 行き過ぎ).
 */
export type Bezier = [number, number, number, number]

/** Arriving, standard. */
export const easeOutQuart: Bezier = [0.25, 1, 0.5, 1]
/** Arriving, snappy — high initial velocity, hard finish, no crawl to the mark. */
export const easeOutQuint: Bezier = [0.23, 1, 0.32, 1]
/** Wind whipping out; something already fast when it appears. */
export const easeOutExpo: Bezier = [0.16, 1, 0.3, 1]
/** Leaving the frame — departs at speed, not at its slowest. */
export const easeInCubic: Bezier = [0.55, 0.055, 0.675, 0.19]
/** Gravity: a fall accelerates. */
export const gravity: Bezier = [0.55, 0, 0.9, 0.45]
/** A shape morphing on screen. */
export const easeInOutQuart: Bezier = [0.76, 0, 0.24, 1]
/** Gentle inout for small rigid moves. */
export const easeInOutCubic: Bezier = [0.65, 0, 0.35, 1]
/** Pen stroke: leaves fast, eases into its stop. */
export const pen: Bezier = [0.45, 0, 0.15, 1]
/** One-beat gesture with built-in anticipation and overshoot (sag → drive → past → settle). */
export const windupOvershoot: Bezier = [0.42, -0.32, 0.28, 1.26]
/** Small overshoot on a settle. */
export const settleBack: Bezier = [0.34, 1.56, 0.64, 1]

import type { CSSProperties } from 'react'
import type { GestureHandle, GestureTrigger } from './useGesture'

export interface GestureIconProps {
  /** Rendered size in px (icons are drawn on a 24-unit grid). */
  size?: number
  /** Stroke/fill color. Defaults to currentColor. */
  color?: string
  strokeWidth?: number
  trigger?: GestureTrigger
  className?: string
  style?: CSSProperties
  /** Imperative control: handleRef.current.play() */
  handleRef?: React.Ref<GestureHandle>
  'aria-label'?: string
}

/** Standard props forwarded to every icon's root <svg>. */
export const svgDefaults = {
  xmlns: 'http://www.w3.org/2000/svg',
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
} as const
